parameters.new_string:
private formatAjvErrors(errors: ErrorObject[]): string {
  return errors
    .map(err => {
      let path = err.instancePath;
      if (err.keyword === 'required' && (err.params as any).missingProperty) {
        const missingProperty = (err.params as any).missingProperty;
        path = path ? `${path}/${missingProperty}` : missingProperty;
      }
      if (!path || path === '') path = 'input';
      return `${path} ${err.message}`;
    })
    .join(', ');
}

import {ToolRegistry} from './registry.js';
import {setLogger} from '../../shared/logger.js';
import type {ToolDefinition} from '../../types/ai.js';

it('validates against the schema current at that call for function-valued definitions', async () => {
  const registry = new ToolRegistry();
  let schema: any;

  registry.register(
    () => ({
      name: 'dynamic_tool',
      description: 'test',
      inputSchema: schema,
    }),
    async () => 'ok'
  );

  // First call: require location
  schema = {
    type: 'object',
    properties: {location: {type: 'string'}},
    required: ['location'],
  };
  const response1 = await registry.execute('dynamic_tool', {});
  expect(response1.result).toMatch(/location.*required/);

  // Second call: require age
  schema = {
    type: 'object',
    properties: {age: {type: 'number'}},
    required: ['age'],
  };
  const response2 = await registry.execute('dynamic_tool', {});
  expect(response2.result).toMatch(/age.*required/);
});

